import re,html
def T(p):
  t=open(p,encoding='utf-8',errors='replace').read()
  t=re.sub(r'(?s)<script.*?</script>|<style.*?</style>','',t)
  return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',t)))
